BEGIN;
CREATE FUNCTION pg_temp.assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION '%',message; END IF; END $$;
CREATE FUNCTION pg_temp.denied(sql text,expected text DEFAULT 'P0001') RETURNS void LANGUAGE plpgsql AS $$ DECLARE actual text; BEGIN BEGIN EXECUTE sql; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS actual=RETURNED_SQLSTATE; END; IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Expected %, got %: %',expected,actual,sql; END IF; END $$;
INSERT INTO auth.users(id,email) VALUES('ae000000-0000-4000-8000-000000000001','precision-admin@example.invalid'),('ae000000-0000-4000-8000-000000000002','precision-user@example.invalid');
INSERT INTO public.user_roles(user_id,role,moderation_status) VALUES('ae000000-0000-4000-8000-000000000001','admin','active') ON CONFLICT(user_id) DO UPDATE SET role='admin';
INSERT INTO public.ai_models(id,provider,provider_model_id,display_name,status,generator_compatible,generator_enabled,quality_check_compatible,quality_check_enabled)
SELECT ('ae100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'openai','precision-'||n,'Precision '||n,'enabled',true,true,true,true FROM generate_series(1,6)n;
SELECT set_config('request.jwt.claim.sub','ae000000-0000-4000-8000-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT public.admin_set_ai_model_default('generator','precision-1');
SELECT public.admin_set_ai_model_default('quality_check','precision-1');
SELECT public.admin_set_ai_model_default('ai_tools','precision-1');
SELECT public.admin_set_ai_model_default('legacy','precision-5');
RESET ROLE;
INSERT INTO public.user_roles(user_id,role,moderation_status) VALUES('ae000000-0000-4000-8000-000000000002','user','active') ON CONFLICT(user_id) DO NOTHING;
CREATE TEMP TABLE operation_defaults AS SELECT key,value FROM public.app_settings WHERE key IN ('ai_generator_default_model','ai_quality_check_default_model','ai_tools_default_model');
DO $$ DECLARE f text; r text; BEGIN
FOREACH f IN ARRAY ARRAY['auxiliary_model_use_start_internal(uuid,text,uuid,uuid,text,uuid)','auxiliary_model_use_receipt_internal(uuid,uuid)'] LOOP
 PERFORM pg_temp.assert(has_function_privilege('service_role','public.'||f,'EXECUTE'),'Server RPC permitted');
 FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP PERFORM pg_temp.assert(NOT has_function_privilege(r,'public.'||f,'EXECUTE'),'No browser dispatch forgery'); END LOOP;
END LOOP;
PERFORM pg_temp.assert((SELECT relrowsecurity FROM pg_class WHERE oid='public.ai_auxiliary_model_uses'::regclass),'Uses RLS');
PERFORM pg_temp.assert(NOT has_table_privilege('authenticated','public.ai_auxiliary_model_uses','SELECT,INSERT,UPDATE,DELETE'),'No direct client uses access');
END $$;
INSERT INTO public.ai_auxiliary_requests(id,user_id,operation,request_key,status,execution_token) VALUES
('ae200000-0000-4000-8000-000000000001','ae000000-0000-4000-8000-000000000002','song_setup_assistant','ae300000-0000-4000-8000-000000000001','processing','ae400000-0000-4000-8000-000000000001'),
('ae200000-0000-4000-8000-000000000002','ae000000-0000-4000-8000-000000000002','song_analyzer',gen_random_uuid(),'processing',gen_random_uuid());
SET LOCAL ROLE service_role;
SELECT public.auxiliary_model_use_start_internal('ae000000-0000-4000-8000-000000000002','song_setup_assistant','ae300000-0000-4000-8000-000000000001','ae400000-0000-4000-8000-000000000001','precision-2','ae500000-0000-4000-8000-000000000001');
RESET ROLE;
SELECT pg_temp.assert('active_auxiliary'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='precision-2'))),'Specific active auxiliary blocks its own model');
SELECT pg_temp.assert(NOT 'active_auxiliary'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='precision-3'))),'Other model and unlabelled legacy requests do not block');
INSERT INTO public.user_model_access(user_id,access_mode,allowed_models) VALUES('ae000000-0000-4000-8000-000000000002','custom',ARRAY['precision-3','precision-4']);
INSERT INTO public.ai_usage_logs(user_id,provider,model,operation,input_tokens,output_tokens,total_tokens,provider_usage_state) VALUES('ae000000-0000-4000-8000-000000000002','openai','precision-3','generate',10,5,15,'final');
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied($q$SELECT public.admin_uninstall_ai_models('[{"id":"ae100000-0000-4000-8000-000000000001","revision":0},{"id":"ae100000-0000-4000-8000-000000000003","revision":0}]',true)$q$);
SELECT pg_temp.denied($q$SELECT public.admin_uninstall_ai_models('[{"id":"ae100000-0000-4000-8000-000000000002","revision":0}]',true)$q$);
RESET ROLE;
SELECT pg_temp.assert((SELECT allowed_models=ARRAY['precision-3','precision-4'] FROM public.user_model_access WHERE user_id='ae000000-0000-4000-8000-000000000002'),'Blocked bulk did not clean grants partially');
SET LOCAL ROLE authenticated;
SELECT public.admin_uninstall_ai_models('[{"id":"ae100000-0000-4000-8000-000000000003","revision":0}]',true);
RESET ROLE;
SELECT pg_temp.assert((SELECT access_mode='custom' AND allowed_models=ARRAY['precision-4'] FROM public.user_model_access WHERE user_id='ae000000-0000-4000-8000-000000000002'),'Remaining custom grants retained in order');
SET LOCAL ROLE authenticated;
SELECT public.admin_uninstall_ai_models('[{"id":"ae100000-0000-4000-8000-000000000004","revision":0},{"id":"ae100000-0000-4000-8000-000000000005","revision":0}]',true);
RESET ROLE;
SELECT pg_temp.assert((SELECT access_mode='inherit' AND cardinality(allowed_models)=0 FROM public.user_model_access WHERE user_id='ae000000-0000-4000-8000-000000000002'),'Last custom grant returns to global-default-only inheritance');
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM public.app_settings WHERE key='ai_model'),'Unused legacy fallback removed safely');
SELECT pg_temp.assert(NOT EXISTS(SELECT * FROM operation_defaults EXCEPT SELECT key,value FROM public.app_settings),'Three operation defaults unchanged');
SELECT pg_temp.assert(EXISTS(SELECT 1 FROM public.ai_usage_logs WHERE model='precision-3'),'Historical finance preserved');
SELECT pg_temp.denied($q$SELECT public.auxiliary_model_use_start_internal('ae000000-0000-4000-8000-000000000002','song_setup_assistant','ae300000-0000-4000-8000-000000000001','ae400000-0000-4000-8000-000000000001','precision-3',gen_random_uuid())$q$);
SELECT pg_temp.denied($q$SELECT public.auxiliary_model_use_start_internal('ae000000-0000-4000-8000-000000000001','song_setup_assistant','ae300000-0000-4000-8000-000000000001','ae400000-0000-4000-8000-000000000001','precision-2',gen_random_uuid())$q$);
SELECT pg_temp.denied($q$SELECT public.mark_auxiliary_ai_provider_started_internal('ae000000-0000-4000-8000-000000000002','song_setup_assistant','ae300000-0000-4000-8000-000000000001','ae400000-0000-4000-8000-000000000001')$q$);
UPDATE auth.users SET banned_until=now()+interval '1 day' WHERE id='ae000000-0000-4000-8000-000000000002';
SELECT pg_temp.denied($q$SELECT public.auxiliary_model_use_start_internal('ae000000-0000-4000-8000-000000000002','song_setup_assistant','ae300000-0000-4000-8000-000000000001','ae400000-0000-4000-8000-000000000001','precision-6',gen_random_uuid())$q$);
UPDATE auth.users SET banned_until=NULL WHERE id='ae000000-0000-4000-8000-000000000002';
-- Failed application state alone cannot release unaccounted dispatches.
UPDATE public.ai_auxiliary_requests SET status='failed' WHERE id='ae200000-0000-4000-8000-000000000001';
SELECT pg_temp.assert('active_auxiliary'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='precision-2'))),'Failure does not fabricate settled usage');
SELECT pg_temp.denied($q$SELECT public.auxiliary_model_use_receipt_internal('ae500000-0000-4000-8000-000000000001',gen_random_uuid())$q$);
INSERT INTO public.ai_usage_outbox(id,payload) VALUES('ae600000-0000-4000-8000-000000000001','{"user_id":"ae000000-0000-4000-8000-000000000002","provider":"openai","model":"precision-2","operation":"song_setup_assistant","input_tokens":10,"output_tokens":5,"total_tokens":15,"provider_usage_state":"final","success":false}');
SELECT public.auxiliary_model_use_receipt_internal('ae500000-0000-4000-8000-000000000001','ae600000-0000-4000-8000-000000000001');
SELECT pg_temp.assert('usage_pending'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='precision-2'))),'Queued financial data still blocks');
-- Receipt association cannot consume another account's financial evidence.
INSERT INTO public.ai_usage_logs(id,user_id,provider,model,operation,provider_usage_state) VALUES('ae600000-0000-4000-8000-000000000002','ae000000-0000-4000-8000-000000000001','openai','precision-2','song_setup_assistant','unknown');
SELECT pg_temp.denied($q$SELECT public.auxiliary_model_use_receipt_internal('ae500000-0000-4000-8000-000000000001','ae600000-0000-4000-8000-000000000002')$q$);
SELECT public.flush_ai_usage_outbox(20);
SELECT pg_temp.assert(NOT 'active_auxiliary'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='precision-2'))),'Known persisted usage releases terminal operation without deleting history');
SET LOCAL ROLE authenticated;
SELECT public.admin_uninstall_ai_models('[{"id":"ae100000-0000-4000-8000-000000000002","revision":0}]',true);
RESET ROLE;
SELECT pg_temp.assert(EXISTS(SELECT 1 FROM public.ai_auxiliary_requests WHERE id='ae200000-0000-4000-8000-000000000001'),'Auxiliary history retained');
SELECT pg_temp.assert(EXISTS(SELECT 1 FROM public.admin_audit_log WHERE details->>'operation'='uninstall' AND details->'models' @> '[{"model":"precision-2"}]'),'Uninstall audited');
-- A completed application job with unknown provider usage is not zero cost.
INSERT INTO public.ai_auxiliary_requests(id,user_id,operation,request_key,status,execution_token) VALUES('ae200000-0000-4000-8000-000000000003','ae000000-0000-4000-8000-000000000002','song_setup_assistant','ae300000-0000-4000-8000-000000000003','processing','ae400000-0000-4000-8000-000000000003');
SELECT public.auxiliary_model_use_start_internal('ae000000-0000-4000-8000-000000000002','song_setup_assistant','ae300000-0000-4000-8000-000000000003','ae400000-0000-4000-8000-000000000003','precision-6','ae500000-0000-4000-8000-000000000003');
INSERT INTO public.ai_usage_logs(id,user_id,provider,model,operation,provider_usage_state) VALUES('ae600000-0000-4000-8000-000000000003','ae000000-0000-4000-8000-000000000002','openai','precision-6','song_setup_assistant','unknown');
SELECT public.auxiliary_model_use_receipt_internal('ae500000-0000-4000-8000-000000000003','ae600000-0000-4000-8000-000000000003');
UPDATE public.ai_auxiliary_requests SET status='completed',result='{"offline":"retained"}' WHERE id='ae200000-0000-4000-8000-000000000003';
SELECT pg_temp.assert('active_auxiliary'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='precision-6'))),'Unknown usage stays unresolved after completed UI job');
SELECT public.settle_ai_usage_internal('{"id":"ae600000-0000-4000-8000-000000000003","user_id":"ae000000-0000-4000-8000-000000000002","provider":"openai","model":"precision-6","operation":"song_setup_assistant","provider_usage_state":"final","input_tokens":10,"output_tokens":5,"total_tokens":15,"success":true}');
SELECT pg_temp.assert(NOT 'active_auxiliary'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='precision-6'))),'Reconciled receipt releases model');
SET LOCAL ROLE authenticated;
SELECT public.admin_set_ai_model_default('legacy','precision-6');
RESET ROLE;
DELETE FROM public.app_settings WHERE key IN ('ai_quality_check_default_model','ai_tools_default_model');
UPDATE public.ai_models SET status='disabled' WHERE provider_model_id NOT IN ('precision-1','precision-6');
UPDATE public.ai_models SET quality_check_enabled=false WHERE provider_model_id='precision-1';
SELECT pg_temp.assert('legacy_fallback'=ANY(public.ai_model_uninstall_reasons((SELECT m FROM public.ai_models m WHERE provider_model_id='precision-6'))),'No invalid last fallback when operation settings are missing');
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied($q$SELECT public.admin_uninstall_ai_models('[{"id":"ae100000-0000-4000-8000-000000000006","revision":0}]',true)$q$);
RESET ROLE;
UPDATE public.ai_models SET quality_check_enabled=true WHERE provider_model_id='precision-1';
SET LOCAL ROLE authenticated;
SELECT public.admin_uninstall_ai_models('[{"id":"ae100000-0000-4000-8000-000000000006","revision":0}]',true);
RESET ROLE;
SELECT pg_temp.assert((SELECT value->>'model'='precision-1' FROM public.app_settings WHERE key='ai_model'),'Legacy fallback automatically points to a compatible remaining model');
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM public.app_settings WHERE key IN ('ai_quality_check_default_model','ai_tools_default_model')),'Missing operation defaults not silently changed');
SELECT pg_temp.assert(EXISTS(SELECT 1 FROM public.ai_auxiliary_requests WHERE result->>'offline'='retained'),'Historical result retained');
ROLLBACK;
